import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import vm from 'node:vm';
import { rpgDefinition, buySword } from '../dist/rpg-example.js';

const sandbox = { crypto, TextEncoder, structuredClone, setTimeout, clearTimeout, console: { info() {}, error() {}, warn() {}, log() {} } };
const extensionCode = (await readFile('dist/index.js', 'utf8')).replaceAll('import.meta.url', JSON.stringify('http://localhost/solve/index.js'));
vm.runInNewContext(extensionCode, sandbox, { filename: 'solve-bundle.js' });
const api = sandbox.SOLVE;
const { version } = JSON.parse(await readFile('package.json', 'utf8'));
assert.equal(api.version, version);
assert.equal(api.VERSION, version);
const manifest = JSON.parse(await readFile('dist/manifest.json', 'utf8'));
assert.equal(manifest.version, version);
assert.equal(typeof api.openDebugger, 'function');
assert.equal(typeof api.compileAuthorDefinition, 'function');
assert.equal(typeof api.compose, 'function');
assert.equal(typeof api.registerWorldInfo, 'function');
assert.equal(typeof api.readWorldInfo, 'function');
assert.equal(typeof api.IndexedDbCache.prototype.getStats, 'function');
assert.equal(typeof api.IndexedDbCache.prototype.pruneSnapshots, 'function');
assert.equal(typeof api.getGuide, 'function');
assert.equal(typeof api.author, 'function');
assert.ok((await readFile('dist/debug.html', 'utf8')).includes('debug.js'));
assert.ok((await readFile('dist/debug.css', 'utf8')).includes('--green'));
assert.ok((await readFile('dist/debug.js', 'utf8')).length > 10000);
const inlineHtml = await readFile('dist/debug-inline.html', 'utf8');
assert.equal((inlineHtml.match(/<\/script>/gu) ?? []).length, 1, '内联面板不能被JS字符串中的标签提前截断');
const inlineScript = inlineHtml.match(/<script>([\s\S]*)<\/script>/u)?.[1];
assert.ok(inlineScript);
new vm.Script(inlineScript);
const embeddedCode = await readFile('dist/embedded.js', 'utf8');
assert.equal(/<\/script/iu.test(embeddedCode), false, '助手内联脚本不能含HTML结束标签');
const parent = vm.createContext({ crypto, TextEncoder, structuredClone, setTimeout, clearTimeout, console: sandbox.console, document: { body: null, createElement: () => ({ remove() {} }), head: { append(script) { vm.runInContext(script.textContent, parent); } } } });
parent.SillyTavern = { getContext: () => ({}) };
const iframe = vm.createContext({ window: { parent, addEventListener() {} } });
vm.runInContext(embeddedCode, iframe);
assert.equal(parent.SOLVE.version, version);
assert.equal(typeof parent.SOLVE.compileAuthorDefinition, 'function');
assert.equal(typeof parent.SOLVE.registerWorldInfo, 'function');
assert.equal(typeof vm.runInContext('SOLVE.registerWorldInfo', iframe), 'function');
assert.equal(typeof vm.runInContext('SOLVE.getGuide', iframe), 'function');
assert.equal(typeof vm.runInContext('SOLVE.author', iframe), 'function');
assert.equal(vm.runInContext('SOLVE.version', iframe), version);
assert.equal(parent.SOLVE.distribution().native, false);
assert.equal(parent.SOLVE.distribution().providers[0].kind, 'embedded');
const host = await import('../dist/sillytavern.js');
assert.equal(typeof host.SolveSessionManager, 'function');
assert.equal(typeof host.attachSillyTavern, 'function');
assert.equal(typeof host.readWorldInfoSelection, 'function');
const definition = await api.compile(rpgDefinition);
const core = new api.SolveCore(definition);
const result = await core.execute(buySword, await core.initialize());
assert.equal(result.feedback.length, 0);
assert.equal(result.state.data.characters.player.gold, 70);
assert.equal(result.state.data.characters.player.inventory.sword.name, '铁剑');
assert.ok(api.toJson(definition, result.state).includes('"@player"'));
assert.ok(api.toToon(definition, result.state).includes('@player'));
const examples = await import('../dist/author-examples.js');
const simple = new api.SolveCore(await api.compile(examples.simpleDefinition));
assert.equal((await simple.execute(examples.takeDamage, await simple.initialize())).state.data.hp, 90);
const authored = await examples.compileWorldInfoExample();
const modular = new api.SolveCore(authored.definition), modularState = await modular.initialize();
assert.equal(modularState.data.characters.player.hp, 95);
const purchased = await modular.execute(examples.buySword, modularState);
assert.equal(purchased.feedback.length, 0);
assert.equal(purchased.state.data.characters.player.gold, 70);
assert.equal(purchased.state.data.characters.player.inventory.sword.name, '铁剑');
assert.equal(modularState.engineState.activeModules.combat, false);
assert.equal(authored.ir.irFormatVersion, '1');
const conditional = await examples.compileConditionalGuideExample();
const conditionalCore = new api.SolveCore(conditional.definition), injured = await conditionalCore.initialize();
const selectedGuide = api.guide(conditional.definition, injured);
assert.match(selectedGuide, /重伤时/u); assert.match(selectedGuide, /低血量时/u); assert.doesNotMatch(selectedGuide, /购买时/u);
const recovered = await conditionalCore.execute({ $set: { '@player.hp': 80 } }, injured);
assert.doesNotMatch(api.guide(conditional.definition, recovered.state), /重伤时|低血量时/u);
const inlinePerson = new api.SolveCore(await api.compile(examples.inlinePersonDefinition));
assert.equal((await inlinePerson.initialize()).data.player.hp, 100);
const inlineShop = new api.SolveCore(await api.compile(examples.inlineShopDefinition));
const boughtInline = await inlineShop.execute(examples.inlineBuySword, await inlineShop.initialize());
assert.equal(boughtInline.state.data.player.gold, 70); assert.equal(boughtInline.state.data.player.inventory.sword.name, '铁剑');
const inlineWorkflow = await examples.compileInlineWorkflowExample(), workflowCore = new api.SolveCore(inlineWorkflow.definition), workflowState = await workflowCore.initialize();
assert.equal(workflowState.data.player.hp, 20); assert.match(api.guide(inlineWorkflow.definition, workflowState), /重伤时/u);
const workflowView = api.project(inlineWorkflow.definition, workflowState, { view: 'narrative' });
assert.equal(workflowView['@player'].secret, undefined); assert.equal(workflowView.displayMode, 'narrative');
console.log('构建包验证通过：三载体、父页面执行、内嵌面板语法和跨上下文定义可运行。');
